export const menuIcon='<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg>';
export function bindMobileNavigation(root){const button=root.querySelector('[data-mobile-menu]'),nav=root.querySelector('[data-mobile-navigation]');if(!button||!nav)return;const marker=root.firstElementChild,controller=new AbortController();const close=()=>{nav.classList.remove('is-open');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label','Open navigation menu');};button.onclick=()=>{const open=!nav.classList.contains('is-open');nav.classList.toggle('is-open',open);button.setAttribute('aria-expanded',String(open));button.setAttribute('aria-label',open?'Close navigation menu':'Open navigation menu');};nav.addEventListener('click',e=>{if(e.target.closest('a,button'))close();},{signal:controller.signal});root.addEventListener('click',e=>{if(!e.target.closest('[data-mobile-menu],[data-mobile-navigation]'))close();},{signal:controller.signal});root.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('is-open')){close();button.focus();}},{signal:controller.signal});const observer=new MutationObserver(()=>{if(!marker.isConnected){controller.abort();observer.disconnect();}});observer.observe(root,{childList:true});}
